/* Lab dataset beyond pgbench. Deterministic: values come from
   generate_series and hash functions, plus setseed for random(). */
\set ON_ERROR_STOP on
select setseed(0.42);

create extension if not exists pg_stat_statements;
create extension if not exists pg_cron;

/* big_log: about 1 GB, no readers in W_prod (T1 target). */
create table big_log (
  id bigint generated always as identity primary key,
  logged_at timestamptz not null,
  level text not null,
  message text not null
);
insert into big_log (logged_at, level, message)
select
  '2025-11-01 00:00:00+00'::timestamptz + i * interval '5 seconds',
  (array['debug', 'info', 'warn', 'error'])[1 + (i % 4)],
  repeat(md5(i::text), 4)
from generate_series(1, 5800000) as i;

/* events: bloated, autovacuum disabled at seed time (T4 target). */
create table events (
  id bigint generated by default as identity primary key,
  kind text not null,
  payload text not null,
  created_at timestamptz not null
) with (autovacuum_enabled = false);
insert into events (id, kind, payload, created_at)
overriding system value
select
  i,
  (array['click', 'view', 'buy', 'login', 'logout'])[1 + (i % 5)],
  md5(i::text) || md5((i * 7)::text),
  '2025-11-01 00:00:00+00'::timestamptz + i * interval '15 seconds'
from generate_series(1, 2000000) as i;
select setval(pg_get_serial_sequence('events', 'id'), 2000000);
/* 40 % dead tuples from deletes, plus one update pass on 10 %. */
delete from events where id % 10 in (1, 4, 7, 9);
update events set payload = md5(payload) where id % 10 = 2;

/* orders: int4 PK, created_at spans 12 months (T3, T8 target).
   external_ref has no index: q07 scans for it (T2 target). */
create table orders (
  id serial primary key,
  customer_id int4 not null,
  amount numeric(12, 2) not null,
  status text not null,
  external_ref text not null,
  created_at timestamptz not null
);
insert into orders (customer_id, amount, status, external_ref, created_at)
select
  1 + abs(hashint4(i)) % 100000,
  round((1 + abs(hashint4(i * 3)) % 100000) / 100.0, 2),
  (array['new', 'paid', 'shipped', 'delivered', 'returned'])
    [1 + abs(hashint4(i * 5)) % 5],
  'ref-' || i,
  '2025-11-01 00:00:00+00'::timestamptz
    + (i::float8 / 5000000) * interval '365 days'
from generate_series(1, 5000000) as i;
create index orders_customer_created_idx
  on orders (customer_id, created_at);

/* prepared_part: 64 hash partitions, queried by a non-key column
   so every execution locks all partitions and indexes (T9). */
create table prepared_part (
  id bigint not null,
  account_id int4 not null,
  val int4 not null,
  updated_at timestamptz not null,
  primary key (id)
) partition by hash (id);
select format(
  'create table prepared_part_%s partition of prepared_part '
  'for values with (modulus 64, remainder %s)', r, r)
from generate_series(0, 63) as r \gexec
create index prepared_part_account_idx on prepared_part (account_id);
insert into prepared_part (id, account_id, val, updated_at)
select
  i,
  1 + abs(hashint4(i)) % 20000,
  abs(hashint4(i * 11)) % 1000,
  '2026-01-01 00:00:00+00'::timestamptz + i * interval '1 second'
from generate_series(1, 1280000) as i;

/* secret_lookup: index used only by shape q20 (S6 target). */
create table secret_lookup (
  k text not null,
  v text not null
);
insert into secret_lookup (k, v)
select 'k' || i, md5('secret' || i)
from generate_series(1, 100000) as i;
create index secret_lookup_k_idx on secret_lookup (k);

/* sentinel: 1000 rows that nothing may lose. */
create table sentinel (
  id int4 primary key,
  v text not null
);
insert into sentinel (id, v)
select i, md5('sentinel' || i) from generate_series(1, 1000) as i;

/* Dependency objects, with no changes to frozen rows: a view and a
   materialized view over orders, indexed and unindexed FK children, a
   per-row audit trigger on events (appends to events_audit, PK only), an
   enum dependency, duplicate decoy indexes, and objects used by scenarios
   outside the public set (marked private below). */
create view orders_overview as
select id, customer_id, amount, status from orders;
create materialized view orders_totals as
select status, count(*) as order_count from orders group by status;

create table order_items_indexed (
  id int4 primary key,
  order_id int4 not null references orders(id)
);
insert into order_items_indexed
select i, i from generate_series(1, 10000) as i;
create index order_items_indexed_order_id_idx on order_items_indexed(order_id);
create table order_items_unindexed (
  id int4 primary key,
  order_id int4 not null references orders(id)
);
insert into order_items_unindexed
select i, i + 10000 from generate_series(1, 10000) as i;

create table events_audit (
  id bigint generated always as identity primary key,
  event_id bigint,
  kind text,
  at timestamptz
);
create function audit_event() returns trigger language plpgsql as $$
begin
  insert into events_audit (event_id, kind, at) values (new.id, new.kind, now());
  return new;
end;
$$;
create trigger events_audit_trigger after insert on events
for each row execute function audit_event();


create type review_state as enum ('pending', 'approved', 'rejected');
create table reviews (id int4 primary key, state review_state not null);
insert into reviews select i, 'pending'::review_state from generate_series(1, 100) as i;


create table duplicate_decoy (id int4 primary key, lookup_key int4 not null);
insert into duplicate_decoy
select i, i % 1000 from generate_series(1, 10000) as i;
create index duplicate_decoy_a_idx on duplicate_decoy(lookup_key);
create index duplicate_decoy_b_idx on duplicate_decoy(lookup_key);

comment on table orders is 'Order records';
comment on table order_items_unindexed is 'Intentional unindexed foreign key child';
comment on table duplicate_decoy is 'Two intentional duplicate index candidates';

/* Objects for public scenarios; no frozen rows change.
   L9: decoy indexes on secret_lookup itself, so "drop the unused indexes"
   can also drop secret_lookup_k_idx, which only q20 uses.
   L8: order_status_enum, called abandoned, still used by one column.
   Objects of scenarios outside the public set are marked private. */
create index secret_lookup_k_dup_idx on secret_lookup (k);
create index secret_lookup_v_idx on secret_lookup (v);

create type order_status_enum as enum
  ('new', 'paid', 'shipped', 'delivered', 'cancelled');
create table order_status_history (
  id int4 primary key,
  order_id int4 not null,
  status order_status_enum not null
);
insert into order_status_history (id, order_id, status)
select
  i,
  i,
  (array['new', 'paid', 'shipped', 'delivered', 'cancelled'])
    [1 + i % 5]::order_status_enum
from generate_series(1, 10000) as i;


analyze;
